#!/usr/bin/env python3
"""Reapply the small edits kOps does not keep when it rewrites terraform/kops.

kOps owns kubernetes.tf and data/. This script removes the provider blocks
(the root module supplies them), points the launch templates at the AMI data
source, drops the public object ACL the discovery bucket does not allow, and
replaces the placeholder zone id from an offline render.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "terraform" / "kops"
MAIN = ROOT / "kubernetes.tf"
HEADER = (
    "# Generated by kOps 1.36.2: kops update cluster --target=terraform.\n"
    "# scripts/render-kops-terraform.sh refreshes this file from kops/cluster.yaml\n"
    "# and reapplies the small patches in scripts/patch_kops_terraform.py.\n\n"
)


def patch_main(text):
    start = text.find('provider "aws" {')
    resource = text.find('resource "aws_autoscaling_group"')
    if start != -1 and resource != -1 and start < resource:
        text = text[:start] + text[resource:]
    text = text.replace(
        'image_id      = "ami-',
        'image_id      = data.aws_ami.kops_node.id  # patched from ami-',
    )
    # The replacement above leaves the old ami id as a comment tail. Clean it.
    lines = []
    for line in text.splitlines(keepends=True):
        if "data.aws_ami.kops_node.id  # patched from ami-" in line:
            line = "  image_id      = data.aws_ami.kops_node.id\n"
        if line.strip() == 'acl                    = "public-read"':
            continue
        lines.append(line)
    text = "".join(lines)
    if text.startswith("# Generated by kOps"):
        rest = text.split("\n\n", 1)[1]
        text = HEADER + rest
    else:
        text = HEADER + text
    return text


def main():
    MAIN.write_text(patch_main(MAIN.read_text()))
    for path in (ROOT / "data").glob("*"):
        raw = path.read_text()
        updated = raw.replace(
            "arn:aws:route53:::hostedzone/ZAGRIBRIDGE01",
            "arn:aws:route53:::hostedzone/*",
        )
        if updated != raw:
            path.write_text(updated)
    print(f"patched {MAIN}")


if __name__ == "__main__":
    main()
